class Node { int val; Node left, right; Node(int v){ val = v; } }

void inorder(Node n) {              // Left, Root, Right
    if (n == null) return;
    inorder(n.left);
    System.out.print(n.val + " ");  // visit root between children
    inorder(n.right);
}

void levelOrder(Node root) {        // BFS with a queue
    if (root == null) return;
    Queue<Node> q = new ArrayDeque<>();
    q.offer(root);
    while (!q.isEmpty()) {
        Node n = q.poll();
        System.out.print(n.val + " ");
        if (n.left != null)  q.offer(n.left);
        if (n.right != null) q.offer(n.right);
    }
}
// On a BST, inorder prints values in ascending sorted order.
