class Node { int val; Node left, right; Node(int v){ val = v; } }

boolean search(Node n, int target) {       // O(h)
    while (n != null) {
        if (target == n.val) return true;
        n = (target < n.val) ? n.left : n.right;  // go one side only
    }
    return false;
}

// Validity: every node must stay within (low, high) bounds
boolean isBST(Node n, long low, long high) {
    if (n == null) return true;
    if (n.val <= low || n.val >= high) return false;   // whole-subtree rule
    return isBST(n.left, low, n.val) && isBST(n.right, n.val, high);
}
// call: isBST(root, Long.MIN_VALUE, Long.MAX_VALUE)
