class Node { int val; Node left, right; Node(int v){ val = v; } }

int height(Node node) {
    if (node == null) return 0;                 // empty subtree (node count)
    int lh = height(node.left);
    int rh = height(node.right);
    return 1 + Math.max(lh, rh);                // root contributes 1
}

//        1
//       / \
//      2   3
//     /
//    4
// height(4)=1; height(2)=1+max(1,0)=2; height(3)=1; height(1)=1+max(2,1)=3
